<?php require_once __DIR__.'/../config/config.php';require_admin();$error='';if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();if(!admin_can('owner'))$error='Only the owner role can create or change administrator accounts.';else{$name=trim((string)($_POST['name']??''));$email=trim((string)($_POST['email']??''));$pass=(string)($_POST['password']??'');$role=(string)($_POST['role']??'editor');if($name===''||!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($pass)<12||!in_array($role,['owner','admin','editor'],true))$error='Enter valid details and a password of at least 12 characters.';else{try{$q=$pdo->prepare('INSERT INTO admin_users(name,email,password_hash,role) VALUES(?,?,?,?)');$q->execute([$name,$email,password_hash($pass,PASSWORD_DEFAULT),$role]);log_admin('admin_user.create','Created '.$email.' role '.$role);flash('notice','Administrator account created.');header('Location: users.php');exit;}catch(Throwable $e){$error='Could not create account. The email may already exist.';}}}}$pageTitle='User accounts & roles';$active='users';$rows=$pdo->query('SELECT id,name,email,role,created_at FROM admin_users ORDER BY created_at DESC')->fetchAll();require __DIR__.'/_layout.php';?><section class="welcome-row"><div><p class="eyebrow">ACCESS CONTROL</p><h1>People with <em>access.</em></h1><p class="muted">Admin accounts are separate from public client accounts.</p></div></section><?php if($error):?><div class="alert"><?=e($error)?></div><?php endif;?><?php if(admin_can('owner')):?><section class="panel form-panel"><h2>Add administrator</h2><form method="post" class="form-grid"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><label>Name<input name="name" required></label><label>Email<input name="email" type="email" required></label><label>Password (12+ characters)<input name="password" type="password" minlength="12" required></label><label>Role<select name="role"><option value="editor">Editor</option><option value="admin">Admin</option><option value="owner">Owner</option></select></label><div class="span-2"><button class="btn btn-primary">Create admin account</button></div></form></section><?php endif;?><section class="panel"><div class="table-wrap"><table><thead><tr><th>NAME</th><th>EMAIL</th><th>ROLE</th><th>CREATED</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['name'])?></td><td><?=e($r['email'])?></td><td><?=e($r['role'])?></td><td><?=e($r['created_at'])?></td></tr><?php endforeach;?></tbody></table></div></section><?php require __DIR__.'/_footer.php';?>